SELECT DECODE(KODE_BA,'2122','2131',KODE_BA) ba, KODE_AFD afd, COALESCE(NULLIF(TAHUN_TANAM,''),'-') thn, COALESCE(NULLIF(MATURITY_STATUS,''),'-') ms, KATEGORI_TANAH kt, ROUND(SUM(HEKTAR),2) ha, ROUND(SUM(COALESCE(JML_POKOK,0))) pokok, COUNT(*) nblok FROM PRD_DB_INTEGRATION.INT_PANEN.INT_HEKTAR_BLOK WHERE KODE_BA IN ('2121','2124','2131','2122') AND DATE_TRUNC('month',BULAN)='2026-09-01' AND HEKTAR>0 GROUP BY 1,2,3,4,5 ORDER BY 1,2,3,4